fn count(s: &str) -> (Int, Int) {
    let mut seen = 0;
    let mut distinct = 0;
    for c in s.chars() {
        seen = seen + 1;
        if seen == 1 {
            distinct = distinct + 1
        }
    }
    (seen, distinct)
}

